// cubic-bezier(x1,y1,x2,y2) -> sample y over t, find peak
function bez(x1,y1,x2,y2){
  const cx=(t,a,b)=>3*(1-t)**2*t*a+3*(1-t)*t*t*b+t**3;
  return (X)=>{ // solve t for x=X by bisection, return y
    let lo=0,hi=1,t;
    for(let i=0;i<60;i++){t=(lo+hi)/2; (cx(t,x1,x2)<X)?lo=t:hi=t;}
    return cx((lo+hi)/2,y1,y2);
  };
}
function peak(name,x1,y1,x2,y2){
  const f=bez(x1,y1,x2,y2); let max=0,at=0;
  for(let i=0;i<=1000;i++){const p=i/1000,y=f(p); if(y>max){max=y;at=p;}}
  console.log(`${name.padEnd(34)} peak y = ${max.toFixed(4)}  (overshoot ${((max-1)*100).toFixed(1)}%) at x=${at.toFixed(2)}`);
  return max;
}
const m = peak('cubic-bezier(.34,1.56,.64,1)  ',0.34,1.56,0.64,1);
peak('cubic-bezier(.34,1.42,.5,1) [ddp]',0.34,1.42,0.5,1);
peak('cubic-bezier(.22,1,.36,1) [expo-out]',0.22,1,0.36,1);

console.log('\n--- bouncePopIn segment peaks with the .34/1.56 curve applied PER interval ---');
const kf=[[0,30,0.86],[0.55,-7,1.045],[0.74,3,0.983],[0.88,-1.5,1.007],[1,0,1]];
for(let i=0;i<kf.length-1;i++){
  const [,y0,s0]=kf[i],[p1,y1,s1]=kf[i+1];
  const yPk=y0+m*(y1-y0), sPk=s0+m*(s1-s0);
  console.log(`  seg ${(kf[i][0]*100).toFixed(0)}%→${(p1*100).toFixed(0)}%  translateY nominal ${String(y1).padStart(5)}px → actual ${yPk.toFixed(2)}px | scale nominal ${s1} → actual ${sPk.toFixed(4)}`);
}
EOF
