input.new_string:
/* ── Entrance tiers ──────────────────────────────────────────────────────
 *
 * Three tiers, each a *two-keyframe* set. Tier 0 is "no class at all" — most
 * chrome (section labels, icons, dividers, timeline rails, anything already
 * inside a morphing container) should simply be there on arrival.
 *
 *   .pt-fade   tier 1  list rows, feed rows, empty states, secondary text
 *   .pt-bounce tier 2  primary content blocks: hero, chart, search row, panel
 *   .pt-pop    tier 3  budgeted accents only — two per vertical, max
 *
 * `.pt-bounce` keeps its historical name (~25 call sites) but is now a plain
 * rise: no scale, no bounce. Set the stagger with --pt-d, capped at 6 steps of
 * --m-stagger; past that a cascade stops reading as motion and starts reading
 * as lag.
 */
@keyframes ptFade { from { opacity: 0; }                             to { opacity: 1; } }
@keyframes ptRise { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
@keyframes ptPop  { from { opacity: 0; transform: translateY(10px) scale(0.96); } to { opacity: 1; transform: none; } }

.pt-fade {
  opacity: 0;
  animation: ptFade var(--m-dur-fade) var(--m-ease-out) both;
  animation-delay: var(--pt-d, 0ms);
}

.pt-bounce {
  opacity: 0;
  animation: ptRise var(--m-dur-enter) var(--m-ease-out) both;
  animation-delay: var(--pt-d, 0ms);
}

.pt-pop {
  opacity: 0;
  animation: ptPop var(--m-dur-pop) var(--m-ease-pop) both;
  animation-delay: var(--pt-d, 0ms);
}

/* Slide from above — the only tier-2 variant, for bars anchored to the top. */
@keyframes slideInFromTop {
  from { opacity: 0; transform: translateY(-10px); }
  to   { opacity: 1; transform: none; }
}

.pt-slide-top {
  opacity: 0;
  animation: slideInFromTop var(--m-dur-enter) var(--m-ease-out) both;
  animation-delay: var(--pt-d, 0ms);
}

/* ── Respect prefers-reduced-motion ─────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-old(property-hero),
  ::view-transition-new(property-hero),
  ::view-transition-old(root),
  ::view-transition-new(root) {
    animation-duration: 0.01ms !important;
  }
  /* These start at opacity 0 and rely on the animation to reveal, so clamping
     the duration is not enough — drop the animation and restore visibility. */
  .pt-fade,
  .pt-bounce,
  .pt-pop,
  .pt-slide-top {
    animation: none !important;
    opacity: 1 !important;
  }
}

