/* Both sides run at the browser's default ~250ms group (geometry) morph. They
   used to run 340/500ms, so the card's contents visibly lagged the box; and an
   overshooting curve on opacity just clamps at 1, making the tail dead time. */
::view-transition-old(property-hero) {
  animation: 250ms var(--m-ease-soft) both pt-fade-out;
}
::view-transition-new(property-hero) {
  animation: 250ms var(--m-ease-out) both pt-fade-in;
}

