// while the animation runs under a paused-and-scrubbed WAAPI object.
const measure = async (tag) => {
  await p.goto(`${BASE_URL}/property/tenants`,{waitUntil:"networkidle"});
  await p.waitForTimeout(2500);
  if (tag === "old") await p.addStyleTag({content:LEGACY});
  const out = await p.evaluate(async () => {
    // pick the 4th .pt-bounce (a tenant row) and restart its animation
    const els=[...document.querySelectorAll(".pt-bounce")];
    const el=els[4]||els[0];
    el.style.animation="none"; void el.offsetWidth; el.style.animation="";
    await new Promise(r=>requestAnimationFrame(r));
    const anims=el.getAnimations();
    if(!anims.length) return {err:"no animation on target"};
    const a=anims[0]; a.pause();
    const rows=[];
    for(const t of [0,60,120,180,240,300,360,420,480,540,620,700]){
      a.currentTime=t;
      const cs=getComputedStyle(el);
      const m=new DOMMatrixReadOnly(cs.transform);
      rows.push({t, y:+m.f.toFixed(2), scale:+m.a.toFixed(4), op:+(+cs.opacity).toFixed(2)});
    }
    return {name:a.animationName, dur:a.effect.getTiming().duration, easing:a.effect.getTiming().easing, rows};
  });
  return out;
};
const neu = await measure("new");
const old = await measure("old");
const fmt=(o,label)=>{
  if(o.err){console.log(`${label}: ${o.err}`);return;}
  console.log(`\n${label}  keyframe=${o.name}  dur=${o.dur}ms`);
  console.log("   t(ms)  translateY   scale   opacity");
  for(const r of o.rows) console.log(`   ${String(r.t).padStart(4)}  ${String(r.y).padStart(9)}px  ${String(r.scale).padStart(6)}   ${r.op}`);
  const ys=o.rows.map(r=>r.y);
  let rev=0; for(let i=2;i<ys.length;i++){const d1=ys[i-1]-ys[i-2],d2=ys[i]-ys[i-1]; if(d1*d2<0) rev++;}
  const travel=ys.slice(1).reduce((s,y,i)=>s+Math.abs(y-ys[i]),0);
  console.log(`   → ${rev} direction reversals, ${travel.toFixed(1)}px total travel, scale range ${Math.min(...o.rows.map(r=>r.scale))}–${Math.max(...o.rows.map(r=>r.scale))}`);
};
fmt(old,"BEFORE (legacy override)"); fmt(neu,"AFTER  (current)");
await b.close();
EOF
