107	/** Catmull-Rom → cubic bezier: the prototypes curve, same geometry. */
108	function curve(vals: number[]) {
109	  const W = 1076;
110	  const H = 240;
111	  const TOP = 16;
112	  const BOT = 24;
113	  const pts = vals.length < 2 ? [vals[0] ?? 0, vals[0] ?? 0] : vals;
114	  const m = pts.length;
115	  const P = pts.map((v, i) => [i * (W / (m - 1)), H - BOT - v * (H - TOP - BOT)] as const);
116	  let d = `M${P[0][0].toFixed(1)},${P[0][1].toFixed(1)}`;
117	  for (let i = 1; i < m; i++) {
118	    const p0 = P[i - 1];
119	    const p1 = P[i];
120	    const pm = P[i - 2] ?? p0;
121	    const pn = P[i + 1] ?? p1;
122	    const c1x = p0[0] + (p1[0] - pm[0]) / 6;
123	    const c1y = p0[1] + (p1[1] - pm[1]) / 6;
124	    const c2x = p1[0] - (pn[0] - p0[0]) / 6;
125	    const c2y = p1[1] - (pn[1] - p0[1]) / 6;
126	    d += ` C${c1x.toFixed(1)},${c1y.toFixed(1)} ${c2x.toFixed(1)},${c2y.toFixed(1)} ${p1[0].toFixed(1)},${p1[1].toFixed(1)}`;
127	  }
128	  return { d, P, W, H };
129	}
