const T=["Josh Smith","Ruby Nolan","Ana Patel"].map((n,i)=>{const[f,l]=n.split(" ");return{id:`t${i+1}`,merchantId:MERCHANT_ID,firstName:f,lastName:l,email:`${f}@x.invalid`,phone:`022111111${i}`,propertyAddress:`${12+i*4} Kauri Road`,preferredChannel:"sms",status:"active",createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}});
const b=await chromium.launch({executablePath:CHROMIUM_PATH});
const ctx=await b.newContext({viewport:{width:1194,height:834},hasTouch:true,deviceScaleFactor:1,serviceWorkers:"block"});
const p=await ctx.newPage();
await p.addInitScript(({m})=>{const pl=btoa(JSON.stringify({userId:1,email:"s@x.invalid",merchantId:m,role:"owner"}));localStorage.setItem("authToken",`s.${pl}.d`);localStorage.setItem("merchantId",String(m));localStorage.setItem("taptMode","property");},{m:MERCHANT_ID});
for(const[pat,body]of[["**/api/auth/me",{user:{id:1,email:"s@x.invalid",merchantId:MERCHANT_ID,role:"owner",onboardingCompleted:true}}],["**/api/tutorial/state",{generation:1,autoEnabled:false,pageCount:20,progress:{}}],["**/api/tutorial/**",{}],["**/api/property/tenants",T],["**/api/property/invoices",[]],["**/api/property/schedules",[]],[`**/api/merchants/${MERCHANT_ID}/**`,[]],[`**/api/merchants/${MERCHANT_ID}`,{id:MERCHANT_ID,businessName:"Wallace Property",status:"active"}],[`**/api/merchants/${MERCHANT_ID}/profile`,{id:MERCHANT_ID,businessName:"Wallace Property",status:"active"}]])await p.route(pat,r=>json(r,body));
await p.goto(`${BASE_URL}/property/tenants`,{waitUntil:"networkidle"});
await p.waitForTimeout(2500);
console.log(await p.evaluate(()=>{
  const cs=getComputedStyle(document.documentElement);
  const tok=n=>cs.getPropertyValue(n).trim()||"UNRESOLVED";
  // synth-test: create an element with the same rule tileIn consumers use
  const probe=document.createElement("div");
  probe.style.cssText="position:fixed;left:-9999px;animation:tileIn var(--m-dur-ui) var(--m-ease-out) both";
  document.body.appendChild(probe);
  const pcs=getComputedStyle(probe);
  const r={tokens:{"--m-dur-ui":tok("--m-dur-ui"),"--m-ease-out":tok("--m-ease-out"),"--m-ease-pop":tok("--m-ease-pop"),"--m-dur-enter":tok("--m-dur-enter"),"--m-stagger":tok("--m-stagger")},
    resolvedDuration:pcs.animationDuration,resolvedEasing:pcs.animationTimingFunction,resolvedName:pcs.animationName};
  probe.remove();
  // and the real nav bubble
  const bub=document.querySelector(".tapt-desktop-nav-bubble");
  if(bub){const bcs=getComputedStyle(bub);r.navBubble={duration:bcs.transitionDuration,easing:bcs.transitionTimingFunction};}
  return r;
}));
await b.close();
