64	    }
65	    if (method === "GET" && url === "/api/merchants/77/transactions") {
66	      return jsonResponse([]);
67	    }
68	    if (method === "GET" && url === "/api/merchants/77/stock-items") {
69	      return jsonResponse([]);
70	    }
71	    if (method === "GET" && url === "/api/merchants/77/tapt-stones") {
72	      boardGetCount += 1;
73	      return jsonResponse(boards);
74	    }
75	    if (method === "POST" && url === "/api/transactions") {
76	      const body = JSON.parse(String(init?.body ?? "{}"));
77	      saleBodies.push(body);
78	      return saleHandler(body);
79	    }
80	    if (method === "POST" && url === "/api/merchants/77/tapt-stones") {
81	      const body = JSON.parse(String(init?.body ?? "{}"));
82	      boardBodies.push(body);
83	      return boardHandler(body);
84	    }
85	    throw new Error(`Unhandled test request: ${method} ${url}`);
86	  });
87	}
