130	.dt-rise,
131	.dt-cascade > * {
132	  opacity: 0;
133	  animation: desktopRiseIn var(--m-dur-enter) var(--m-ease-out) both;
134	  animation-delay: calc(var(--dt-i, 0) * var(--m-stagger) + var(--dt-d, 0ms));
135	}
136	
137	/* Auto-index for `.dt-cascade` containers. Six steps is the cascade budget —
138	   past that a stagger stops reading as motion and starts reading as lag, so
139	   anything beyond simply lands on the last step. */
140	.dt-cascade > *:nth-child(1) { --dt-i: 0; }
141	.dt-cascade > *:nth-child(2) { --dt-i: 1; }
142	.dt-cascade > *:nth-child(3) { --dt-i: 2; }
143	.dt-cascade > *:nth-child(4) { --dt-i: 3; }
144	.dt-cascade > *:nth-child(5) { --dt-i: 4; }
145	.dt-cascade > *:nth-child(n + 6) { --dt-i: 5; }
