cd /home/runner/workspace; cat > ./diag-tmp.mjs <<'EOF'
import { mkdir } from "node:fs/promises";
import { chromium } from "playwright";
import { BASE_URL, CHROMIUM_PATH, MERCHANT_ID } from "./scripts/desktop-shots/retail-fixtures.mjs";
const OUT="/tmp/board-picker"; await mkdir(OUT,{recursive:true});
const json=(r,b,s=200)=>r.fulfill({status:s,contentType:"application/json",body:JSON.stringify(b)});
let stones=[
 {id:11,name:"Counter board",stoneNumber:1,paymentUrl:"https://b.example/11",qrCodeUrl:"https://b.example/11/qr"},
 {id:22,name:"Window board",stoneNumber:2,paymentUrl:"https://b.example/22",qrCodeUrl:"https://b.example/22/qr"},
 {id:33,name:"Patio board",stoneNumber:3,paymentUrl:"https://b.example/33",qrCodeUrl:"https://b.example/33/qr"},
];
const b=await chromium.launch({executablePath:CHROMIUM_PATH});
const ctx=await b.newContext({viewport:{width:1194,height:834},hasTouch:true,deviceScaleFactor:2,serviceWorkers:"block"});
const p=await ctx.newPage();
const errs=[]; p.on("pageerror",e=>errs.push(e.message));
p.on("console",m=>m.type()==="error"&&errs.push(m.text()));
await p.addInitScript(({m})=>{const pl=btoa(JSON.stringify({userId:1,email:"s@x.invalid",merchantId:m,role:"owner"}));localStorage.setItem("authToken",`s.${pl}.d`);localStorage.setItem("merchantId",String(m));localStorage.setItem("taptMode","retail");},{m:MERCHANT_ID});
await p.route("**/api/auth/me",r=>json(r,{user:{id:1,email:"s@x.invalid",merchantId:MERCHANT_ID,role:"owner",onboardingCompleted:true}}));
await p.route("**/api/tutorial/state",r=>json(r,{generation:1,autoEnabled:false,pageCount:20,progress:{}}));
await p.route("**/api/tutorial/**",r=>json(r,{}));
await p.route(`**/api/merchants/${MERCHANT_ID}/tapt-stones`,async r=>{
  if(r.request().method()==="POST"){const body=JSON.parse(r.request().postData()||"{}");
    const s={id:44,name:body.name||"Stone 4",stoneNumber:4,paymentUrl:"https://b.example/44",qrCodeUrl:"https://b.example/44/qr"};
    stones=[...stones,s]; return json(r,s);}
  return json(r,stones);});
await p.route(`**/api/merchants/${MERCHANT_ID}/tapt-stones/*`,async r=>{
  const id=Number(r.request().url().split("/").pop());
  const body=JSON.parse(r.request().postData()||"{}");
  stones=stones.map(s=>s.id===id?{...s,name:body.name}:s);
  return json(r,stones.find(s=>s.id===id));});
await p.route(`**/api/merchants/${MERCHANT_ID}/transactions`,r=>json(r,[]));
await p.route(`**/api/merchants/${MERCHANT_ID}/stock-items`,r=>json(r,[]));
await p.route(`**/api/merchants/${MERCHANT_ID}/profile`,r=>json(r,{id:MERCHANT_ID,businessName:"Test Shop",paymentUrl:"https://m.example/pay",qrCodeUrl:"https://m.example/pay/qr"}));
await p.route(`**/api/merchants/${MERCHANT_ID}/**`,r=>json(r,[]));
await p.route(`**/api/merchants/${MERCHANT_ID}`,r=>json(r,{id:MERCHANT_ID,businessName:"Test Shop"}));
await p.goto(`${BASE_URL}/terminal`,{waitUntil:"networkidle"});
await p.waitForTimeout(2500);

const panel = p.locator(".rt-panel");
const shot = async (n) => { await panel.screenshot({path:`${OUT}/${n}.png`}); console.log("  shot:", n); };

await shot("1-initial");
await p.getByRole("button",{name:"payment boards"}).click();
await p.waitForTimeout(320); await shot("2-engaged-sidepop");
await p.getByRole("button",{name:"select board"}).click();
await p.waitForTimeout(120); await shot("3-dropdown-midway");
await p.waitForTimeout(400); await shot("4-dropdown-open");
await p.getByRole("radio",{name:"Window board, board 2"}).click();
await p.waitForTimeout(400); await shot("5-selected");
console.log("  picker label now:", await p.locator(".rt-picker-label").innerText());
await p.locator(".rt-picker-btn").click(); await p.waitForTimeout(400);
await p.getByRole("button",{name:"rename Patio board"}).click();
await p.waitForTimeout(150); await shot("6-renaming");
await p.getByRole("textbox",{name:"rename Patio board"}).fill("Garden bar");
await p.keyboard.press("Enter"); await p.waitForTimeout(600); await shot("7-renamed");
await p.getByRole("button",{name:"create new board"}).click();
await p.waitForTimeout(150);
await p.getByRole("textbox",{name:"new board name"}).fill("Takeaway hatch");
await shot("8-creating");
await p.keyboard.press("Enter"); await p.waitForTimeout(800); await shot("9-created");
console.log("  picker label after create:", await p.locator(".rt-picker-label").innerText());
console.log("  boards now:", stones.map(s=>s.name).join(" | "));
await p.getByRole("button",{name:"payment boards"}).click();
await p.waitForTimeout(400); await shot("10-disengaged");
console.log("  page errors:", errs.length? errs.slice(0,3): "none");
await b.close();
EOF
node ./diag-tmp.mjs; rm -f ./diag-tmp.mjs
